import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int c = sc.nextInt();
        int target = sc.nextInt();

        int foundRow = 0;
        int foundCol = 0;
        int checked = 0;
        search:
        for (int i = 1; i <= r; i++) {
            for (int j = 1; j <= c; j++) {
                int value = sc.nextInt();
                checked++;
                if (value == target) {
                    foundRow = i;
                    foundCol = j;
                    break search;
                }
            }
        }

        if (foundRow == 0) {
            System.out.println("found=none");
        } else {
            System.out.println("found=" + foundRow + "," + foundCol);
        }
        System.out.println("checked=" + checked);
    }
}

